import { Component, EventEmitter, Output } from '@angular/core';
import { FormBuilder, FormGroup } from '@angular/forms';
import { FiltreRecherche } from '../../models/marche.model';

@Component({
  selector: 'app-recherche-marche',
  templateUrl: './recherche-marche.component.html',
  styleUrls: ['./recherche-marche.component.scss']
})
export class RechercheMarcheComponent {
  @Output() search = new EventEmitter<FiltreRecherche>();
  filtersVisible = true;
  searchForm: FormGroup;
  statutOptions = [
    { value: 'ACTIF', label: '✅ Actif' },
    { value: 'EN_COURS', label: '⏳ En cours' },
    { value: 'EN_ATTENTE', label: '⏳ En attente' },
    { value: 'ARCHIVE', label: '📁 Archivé' },
    { value: 'ANNULE', label: '❌ Annulé' }
  ];
  typeOptions = [
    { value: 'PRESTATION_SERVICE', label: 'Prestation de service' },
    { value: 'PRESTATION_INTELLECTUELLE', label: 'Prestation intellectuelle' },
    { value: 'FOURNITURE', label: 'Fourniture' },
    { value: 'TRAVAUX', label: 'Travaux' },
    { value: 'AUTRE', label: 'Autre' }
  ];

  constructor(private fb: FormBuilder) {
    this.searchForm = this.fb.group({
      motCle: [''],
      statut: [''],
      type: [''],
      region: [''],
      departement: [''],
      commune: [''],
      montantMin: [''],
      montantMax: ['']
    });
  }

  onSearch(): void {
    const f = this.searchForm.value;
    this.search.emit({
      motCle: f.motCle || undefined,
      statut: f.statut || undefined,
      type: f.type || undefined,
      region: f.region || undefined,
      departement: f.departement || undefined,
      commune: f.commune || undefined,
      montantMin: f.montantMin || undefined,
      montantMax: f.montantMax || undefined
    });
  }
  resetFilters(): void { this.searchForm.reset(); this.onSearch(); }
}
<div class="recherche-container">
  <div class="recherche-header">
    <h3>🔍 Recherche</h3>
    <button class="btn-toggle" (click)="filtersVisible = !filtersVisible">{{ filtersVisible ? 'Masquer ▲' : 'Afficher ▼' }}</button>
  </div>
  <div class="search-bar">
    <div class="search-input-wrapper">
      <span class="search-icon">🔍</span>
      <input type="text" formControlName="motCle" (input)="onSearch()" placeholder="Rechercher..." class="search-input">
      <button class="btn-clear" *ngIf="searchForm.get('motCle')?.value" (click)="resetFilters()">✕</button>
    </div>
    <button class="btn-search" (click)="onSearch()">Rechercher</button>
  </div>
  <div class="filters-panel" *ngIf="filtersVisible">
    <div class="filters-grid">
      <div class="filter-group"><label>📊 Statut</label><select formControlName="statut" (change)="onSearch()" class="filter-select"><option value="">Tous</option><option *ngFor="let o of statutOptions" [value]="o.value">{{ o.label }}</option></select></div>
      <div class="filter-group"><label>📂 Type</label><select formControlName="type" (change)="onSearch()" class="filter-select"><option value="">Tous</option><option *ngFor="let o of typeOptions" [value]="o.value">{{ o.label }}</option></select></div>
      <div class="filter-group"><label>🗺️ Région</label><input type="text" formControlName="region" (input)="onSearch()" placeholder="Région" class="filter-input"></div>
      <div class="filter-group"><label>📍 Département</label><input type="text" formControlName="departement" (input)="onSearch()" placeholder="Département" class="filter-input"></div>
      <div class="filter-group"><label>🏘️ Commune</label><input type="text" formControlName="commune" (input)="onSearch()" placeholder="Commune" class="filter-input"></div>
      <div class="filter-group"><label>💰 Montant min</label><input type="number" formControlName="montantMin" (input)="onSearch()" placeholder="0" class="filter-input"></div>
      <div class="filter-group"><label>💰 Montant max</label><input type="number" formControlName="montantMax" (input)="onSearch()" placeholder="100000000" class="filter-input"></div>
    </div>
    <button class="btn-reset" (click)="resetFilters()">🔄 Réinitialiser</button>
  </div>
</div>
